import { motion } from "framer-motion";

function Skills() {
  const skills = [
    { name: "React", icon: "⚛️" },
    { name: "Node.js", icon: "🌐" },
    { name: "SQL", icon: "🗄️" },
    { name: "GitHub", icon: "🐙" },
    { name: "TailwindCSS", icon: "🎨" },
  ];

  return (
    <section id="skills" className="py-20 bg-gray-800 text-center">
      <h2 className="text-3xl font-bold text-purple-400 mb-10">Skills</h2>
      <div className="grid grid-cols-2 md:grid-cols-3 gap-8 justify-items-center">
        {skills.map((skill, index) => (
          <motion.div
            key={index}
            className="bg-gray-900 p-6 rounded-lg shadow-lg hover:scale-105 transition-transform"
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.2 }}
          >
            <div className="text-4xl mb-2">{skill.icon}</div>
            <p className="text-lg text-gray-300">{skill.name}</p>
          </motion.div>
        ))}
      </div>
    </section>
  );
}

export default Skills;
